"/us/en/portfolios/orthopaedics/foot-and-ankle": {"template":"capability","metadata":{"title":"Foot and ankle","pageTitle":null,"description":"As one of the world’s leading companies in medical technology, Stryker is dedicated to helping foot and ankle surgeons treat their patients more efficiently while enhancing patient care and the overall healthcare experience. Constantly driven to innovate, we offer a diverse array of advanced medical technologies and a comprehensive portfolio of products. We’re here for the foot and ankle surgeon. We’re here to make healthcare better.","image":"/content/dam/stryker/foot-and-ankle/images/FA-foot-image.jpg","imageAlt":"Foot and Ankle","tags":["stryker:content-type/capability","stryker:capability/foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T13:11:54.000Z","lastPublished":"2026-08-18T19:59:30.000Z","contentID":"OT-AWI-42, 08-2017"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
